/** Independent representations: occupancy map, direct event fold, recursive token AST and civil-day integer formula. */
export function trainOracle(ticks:number,destination:number){const edges=new Map([[0,[2]],[1,[2]],[2,[3]],[3,[4,7]],[4,[5,6]],[5,[]],[6,[]],[7,[8]],[8,[]]]),occupied=new Map([[0,{id:4,dest:8}],[1,{id:3,dest:destination}],[3,{id:2,dest:6}],[4,{id:1,dest:5}],[8,{id:0,dest:8}]]),history=[];function reachable(from:number,to:number){const todo=[from],seen=new Set<number>();while(todo.length){const a=todo.shift()!;if(a===to)return true;if(!seen.has(a)){seen.add(a);todo.push(...edges.get(a)!);}}return false;}for(let n=0;n<ticks;n++){const blocked=new Set(occupied.keys());for(const from of [...edges.keys()].sort((a,b)=>b-a)){const train=occupied.get(from);if(!train)continue;if(train.dest===from){occupied.delete(from);continue;}const target=edges.get(from)!.find(to=>!blocked.has(to)&&reachable(to,train.dest));if(target!==undefined){occupied.delete(from);occupied.set(target,train);blocked.add(target);}}history.push(Array.from({length:9},(_,i)=>occupied.get(i)??null));}return{history,occupied};}
export function qualificationOracle(owned:{no:string;dates:number[]}[],passes:{no:string;qualification:number;date:number}[]){const records=structuredClone(owned);for(const employee of records)for(const row of passes.filter(r=>r.no===employee.no)){if(employee.dates[row.qualification-1]!==0)throw Error('RETAKE');employee.dates[row.qualification-1]=row.date;}return{records:records.sort((a,b)=>a.no.localeCompare(b.no)),counts:Array.from({length:4},(_,i)=>passes.filter(r=>r.qualification===i+1).length),awards:records.filter(r=>passes.some(p=>p.no===r.no)&&r.dates.every(d=>d>0)).map(r=>r.no).sort()};}
export function templateOracle(input:string,table:Record<string,string[]>,escaped=false){const tokens:{char:string;escaped:boolean}[]=[];for(let i=0;i<input.length;i++){const c=input[i];if(escaped&&c==='\\'){if(i+1===input.length)throw Error('DANGLING_ESCAPE');tokens.push({char:input[++i],escaped:true});}else tokens.push({char:c,escaped:false});}const output:string[]=[];let at=0;while(at<tokens.length){const t=tokens[at++];if(t.char==='<'&&!t.escaped){let key='';while(at<tokens.length&&(tokens[at].char!=='>'||tokens[at].escaped))key+=tokens[at++].char;if(at++>=tokens.length)throw Error('MISSING_CLOSE');const xs=table[key];if(!xs||!xs.length)throw Error('MISSING_KEY');for(let i=0;i<xs.length;i++){if(i)output.push('\n');output.push(xs[i]);}}else output.push(t.char);}return output.join('');}
/** March-based Gregorian era decomposition, no production loops or leap helper. */
export function civilOrdinal(y:number,m:number,d:number){y-=m<=2?1:0;const era=Math.floor(y/400),yoe=y-era*400,mp=m+(m>2?-3:9);return era*146097+yoe*365+Math.floor(yoe/4)-Math.floor(yoe/100)+Math.floor((153*mp+2)/5)+d-1;}
export function ordinalCivil(n:number):[number,number,number]{const era=Math.floor(n/146097),doe=n-era*146097,yoe=Math.floor((doe-Math.floor(doe/1460)+Math.floor(doe/36524)-Math.floor(doe/146096))/365),y=yoe+era*400,doy=doe-(365*yoe+Math.floor(yoe/4)-Math.floor(yoe/100)),mp=Math.floor((5*doy+2)/153),d=doy-Math.floor((153*mp+2)/5)+1,m=mp+(mp<10?3:-9);return[y+(m<=2?1:0),m,d];}
